"""Lamport clocks, vector clocks and the happens-before comparison."""
from __future__ import annotations


class LamportClock:
    def __init__(self) -> None:
        self.time = 0

    def tick(self) -> int:
        """A local event: increment, and return the event's timestamp."""
        self.time += 1
        return self.time

    def send(self) -> int:
        """Sending is an event too: tick, and return the timestamp to attach to the message."""
        return self.tick()

    def receive(self, timestamp: int) -> int:
        """Receiving: jump past the message's timestamp. Return the receive event's timestamp."""
