def compare(a: tuple[int, ...], b: tuple[int, ...]) -> str:
    """'before' if a happened before b, 'after' if b happened before a, 'equal', or 'concurrent'."""
    raise NotImplementedError("TODO: compare element-wise")


def compare_versions(a: dict[str, int], b: dict[str, int]) -> str:
    """compare() for version vectors stored as {replica: counter}; a missing replica counts as 0."""
    names = sorted(set(a) | set(b))
    return compare(tuple(a.get(n, 0) for n in names), tuple(b.get(n, 0) for n in names))

