"""Decide whether a history of reads and writes on one register is linearisable or sequentially consistent.

Both questions have the same shape: is there an order of all the operations that (1) a rule allows and
(2) is a legal register history, where every read returns the value of the latest write before it
(or the initial value)? Linearisability's rule respects real time; sequential consistency's respects
only each client's own order.
"""
from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Op:
    client: str
    kind: str        # "w" (write) or "r" (read)
    value: int       # the value written, or the value the read returned
    start: int       # invocation time
    end: int         # response time

    def __str__(self) -> str:
        return f"{self.client}:{self.kind}{self.value}[{self.start},{self.end}]"


def real_time_ok(op: Op, remaining: list[Op]) -> bool:
    """Linearisability: `op` may come next only if no other remaining op ended before `op` started."""
    raise NotImplementedError("TODO")


def program_order_ok(op: Op, remaining: list[Op]) -> bool:
    """Sequential consistency: `op` may come next only if no earlier op of the same client remains."""
    raise NotImplementedError("TODO")


def find_order(history: list[Op], rule, initial: int = 0) -> list[Op] | None:
    """Depth-first search for a legal order allowed by `rule`; return it, or None if there is none.
    Failed (remaining set, register value) states are remembered, so no state is explored twice."""
    ops = sorted(history, key=lambda o: (o.start, o.end))
    order: list[Op] = []
    failed: set[tuple[frozenset, int]] = set()

    def search(remaining: frozenset, value: int) -> bool:
        raise NotImplementedError("TODO: try each op the rule allows; a read must return `value`; recurse")

    return list(order) if search(frozenset(range(len(ops))), initial) else None


def linearizable(history: list[Op], initial: int = 0) -> list[Op] | None:
    return find_order(history, real_time_ok, initial)


def sequentially_consistent(history: list[Op], initial: int = 0) -> list[Op] | None:
    return find_order(history, program_order_ok, initial)

"""A register on three replicas, simulated event by event with random, sometimes long, message delays.

One writer writes 1, 2, 3, ...: it sends each value to all replicas and finishes when two acknowledge.
Readers ask all replicas and take the highest value among the first two replies. With write_back=True a
reader first writes that value back to the replicas and waits for two acknowledgements before returning
it: the ABD algorithm (Attiya, Bar-Noy and Dolev), which makes the register linearisable.
"""
from __future__ import annotations

import heapq
import random

from checker import Op


def simulate(seed: int, write_back: bool, writes: int = 3, readers: int = 3, reads_each: int = 2) -> list[Op]:
    rng = random.Random(seed)
    state = [0, 0, 0]                                   # each replica's value
    queue: list = []
    seq = 0
    history: list[Op] = []
    pending: dict = {}

    def at(time: int, action: str, *args) -> None:
        nonlocal seq
        seq += 1
        heapq.heappush(queue, (time, seq, action, args))

    def delay() -> int:
        """Most messages take 1-10 ms; one in five is slow (40-120 ms), as on a congested network."""
        return rng.randint(1, 10) if rng.random() < 0.8 else rng.randint(40, 120)

    def send_value(t: int, op_id, value: int) -> None:
        """Deliver `value` to every replica; each replica's acknowledgement comes back to op_id."""
        for i in range(3):
            d = delay()
            at(t + d, "apply", i, value)
            at(t + d + delay(), "ack", op_id)

    at(rng.randint(0, 10), "start_write", 1)
    for c in range(readers):
        at(rng.randint(0, 60), "start_read", f"R{c}", 1)

    while queue:
        t, _, action, args = heapq.heappop(queue)
        if action == "apply":
            i, value = args
            state[i] = max(state[i], value)
        elif action == "start_write":
            (value,) = args
            pending[("w", value)] = {"start": t, "acks": 0}
            send_value(t, ("w", value), value)
        elif action == "start_read":
            client, n = args
            op_id = ("r", client, n)
            pending[op_id] = {"start": t, "replies": [], "acks": 0}
            for i in range(3):
                at(t + delay(), "query", op_id, i)
        elif action == "query":
            op_id, i = args
            at(t + delay(), "reply", op_id, state[i])     # the replica answers with what it has now
        elif action == "reply":
            op_id, value = args
            p = pending[op_id]
            p["replies"].append(value)
            if len(p["replies"]) == 2:                    # a majority has answered
                p["value"] = max(p["replies"])
                if write_back:
                    send_value(t, op_id, p["value"])
                else:
                    finish(t, op_id, p, history, at, rng, writes, reads_each)
        elif action == "ack":
            (op_id,) = args
            p = pending[op_id]
            p["acks"] += 1
            if p["acks"] == 2:                            # a majority has acknowledged
                finish(t, op_id, p, history, at, rng, writes, reads_each)
    return history


def finish(t, op_id, p, history, at, rng, writes, reads_each) -> None:
    if op_id[0] == "w":
        value = op_id[1]
        history.append(Op("W", "w", value, p["start"], t))
        if value < writes:
            at(t + rng.randint(1, 10), "start_write", value + 1)
    else:
        _, client, n = op_id
        history.append(Op(client, "r", p["value"], p["start"], t))
        if n < reads_each:
            at(t + rng.randint(1, 20), "start_read", client, n + 1)

from checker import linearizable, sequentially_consistent
from histories import HISTORIES
from quorum_register import simulate


def verdict(history) -> str:
    lin, sc = linearizable(history), sequentially_consistent(history)
    text = f"linearisable: {'yes' if lin else 'no '}  sequentially consistent: {'yes' if sc else 'no '}"
    return text + (f"  order: {' '.join(map(str, lin))}" if lin else "")


if __name__ == "__main__":
    for name, history in HISTORIES.items():
        print(f"{name}:\n    {verdict(history)}")
    for write_back in (False, True):
        bad_lin = bad_sc = 0
        example = None
        for seed in range(500):
            h = simulate(seed, write_back)
            if not linearizable(h):
                bad_lin += 1
                example = example or (seed, h)
            bad_sc += sequentially_consistent(h) is None
        label = "with ABD write-back" if write_back else "quorum reads only  "
        print(f"{label}: {bad_lin} of 500 histories not linearisable, {bad_sc} not sequentially consistent")
        if example:
            seed, h = example
            print(f"    first counterexample (seed {seed}): " + " ".join(map(str, sorted(h, key=lambda o: o.start))))

