"""Raft leader election (section 5.2 of the Raft paper), without log replication.

Each node's log is only the list of its entries' terms: enough for the election restriction.
Node methods never touch the network directly: they call self.sim.send(...), so the simulator in
sim.py (or a test) decides when and whether messages arrive.
"""
from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class RequestVote:
    term: int
    candidate: str
    last_log_index: int
    last_log_term: int


@dataclass(frozen=True)
class VoteReply:
    term: int
    voter: str
    granted: bool


@dataclass(frozen=True)
class AppendEntries:          # a heartbeat: no entries in this lab
    term: int
    leader: str


@dataclass(frozen=True)
class AppendReply:
    term: int
    follower: str
    success: bool


class Node:
    def __init__(self, name: str, peers: list[str], sim, log_terms: tuple[int, ...] = ()) -> None:
        self.name, self.peers, self.sim = name, list(peers), sim
        self.current_term = 0          # persistent state: written to disk before answering any RPC
        self.voted_for: str | None = None
        self.log = list(log_terms)     # the term of each entry; entry i (from 1) is log[i - 1]
        self.role = "follower"
        self.votes: set[str] = set()
        self.leader: str | None = None

    # helpers -----------------------------------------------------------------------------------
    def last_log_index(self) -> int:
        return len(self.log)

    def last_log_term(self) -> int:
        return self.log[-1] if self.log else 0

    def majority(self) -> int:
        return (len(self.peers) + 1) // 2 + 1

    def become_follower(self, term: int) -> None:
        """Adopt a newer term: forget any vote cast in an older term."""
        if term > self.current_term:
            self.current_term, self.voted_for = term, None
        self.role, self.votes = "follower", set()

    def log_is_up_to_date(self, last_term: int, last_index: int) -> bool:
        """Is a log ending (last_term, last_index) at least as up to date as ours? (Raft paper, 5.4.1)"""
        raise NotImplementedError("TODO: compare last terms first, then lengths")

    # events --------------------------------------------------------------------------------------
    def on_election_timeout(self) -> None:
        """No heartbeat in time: start an election for the next term."""
        raise NotImplementedError("TODO: become candidate, new term, vote for self, reset timer, ask every peer")

    def on_request_vote(self, msg: RequestVote) -> VoteReply:
        """Grant at most one vote per term, and only to a candidate whose log is at least as up to date."""
        raise NotImplementedError("TODO: higher term first; then the vote rules; reset the timer when granting")

    def on_vote_reply(self, msg: VoteReply) -> None:
        """Count votes for the current term; a majority makes this node leader."""
        raise NotImplementedError("TODO: step down on a higher term; ignore stale replies; count; become leader")

    def on_append_entries(self, msg: AppendEntries) -> AppendReply:
        """A heartbeat from a leader of this term or a newer one keeps us a follower."""
        if msg.term < self.current_term:
            return AppendReply(self.current_term, self.name, False)
        self.become_follower(msg.term)
        self.leader = msg.leader
        self.sim.reset_election_timer(self)
        return AppendReply(self.current_term, self.name, True)

    def on_append_reply(self, msg: AppendReply) -> None:
        if msg.term > self.current_term:
            self.become_follower(msg.term)

"""A discrete-event simulator for raft.py: random message delays, crashes and partitions, fully seeded."""
from __future__ import annotations

import heapq
import random

from raft import AppendEntries, AppendReply, Node, RequestVote, VoteReply

HEARTBEAT_MS = 50
ELECTION_TIMEOUT_MS = (150, 300)
DELAY_MS = (5, 15)


class Sim:
    def __init__(self, names: list[str], seed: int = 1, logs: dict | None = None,
                 first_timeouts: dict | None = None, verbose: bool = True) -> None:
        self.rng = random.Random(seed)
        self.now = 0
        self.queue: list = []
        self.seq = 0
        self.blocked: set[tuple[str, str]] = set()
        self.verbose = verbose
        self.show_votes = False
        self.leaders: list[tuple[int, int, str]] = []          # (time, term, leader)
        self.timers: dict[str, int] = {}
        self.nodes = {n: Node(n, [p for p in names if p != n], self, tuple((logs or {}).get(n, ())))
                      for n in names}
        for name, node in self.nodes.items():
            self.reset_election_timer(node, (first_timeouts or {}).get(name))
        self.down: set[str] = set()

    # the interface Node uses -----------------------------------------------------------------------
    def send(self, src: str, dst: str, msg) -> None:
        if src in self.down or (src, dst) in self.blocked:
            return
        self._at(self.now + self.rng.randint(*DELAY_MS), self._deliver, src, dst, msg)

    def reset_election_timer(self, node: Node, timeout: int | None = None) -> None:
        self.seq += 1
        self.timers[node.name] = token = self.seq
        timeout = timeout if timeout is not None else self.rng.randint(*ELECTION_TIMEOUT_MS)
        self._at(self.now + timeout, self._timer, node, token)

    def became_leader(self, node: Node) -> None:
        self.leaders.append((self.now, node.current_term, node.name))
        self.log(f"{node.name} becomes leader of term {node.current_term} with votes from {sorted(node.votes)}")
        self._heartbeat(node, node.current_term)

    # scenario controls ---------------------------------------------------------------------------
    def run_until(self, t: int) -> None:
        while self.queue and self.queue[0][0] <= t:
            self.now, _, fn, args = heapq.heappop(self.queue)
            fn(*args)
        self.now = t

    def crash(self, name: str) -> None:
        self.down.add(name)
        self.log(f"{name} crashes")

    def partition(self, *groups: set[str]) -> None:
        self.blocked = {(a, b) for g in groups for h in groups if g is not h for a in g for b in h}
        self.log("partition: " + " | ".join(",".join(sorted(g)) for g in groups))

    def heal(self) -> None:
        self.blocked = set()
        self.log("partition healed")

    def leader_now(self) -> str | None:
        live = [n for n in self.nodes.values() if n.name not in self.down and n.role == "leader"]
        return max(live, key=lambda n: n.current_term).name if live else None

    def log(self, text: str) -> None:
        if self.verbose:
            print(f"t={self.now:>5} ms  {text}")

    # internals -----------------------------------------------------------------------------------
    def _at(self, t: int, fn, *args) -> None:
        self.seq += 1
        heapq.heappush(self.queue, (t, self.seq, fn, args))

    def _timer(self, node: Node, token: int) -> None:
        if node.name in self.down or self.timers.get(node.name) != token or node.role == "leader":
            return
        node.on_election_timeout()
        self.log(f"{node.name} times out and asks for votes in term {node.current_term}")

    def _heartbeat(self, node: Node, term: int) -> None:
        if node.name in self.down or node.role != "leader" or node.current_term != term:
            return
        for peer in node.peers:
            self.send(node.name, peer, AppendEntries(term, node.name))
        self._at(self.now + HEARTBEAT_MS, self._heartbeat, node, term)

    def _deliver(self, src: str, dst: str, msg) -> None:
        node = self.nodes[dst]
        if dst in self.down or (src, dst) in self.blocked:
            return
        was_leader = node.role == "leader"
        if isinstance(msg, RequestVote):
            self.send(dst, src, node.on_request_vote(msg))
        elif isinstance(msg, VoteReply):
            if self.show_votes:
                self.log(f"{msg.voter} {'grants' if msg.granted else 'refuses'} {dst} a vote (term {msg.term})")
            node.on_vote_reply(msg)
        elif isinstance(msg, AppendEntries):
            self.send(dst, src, node.on_append_entries(msg))
        elif isinstance(msg, AppendReply):
            node.on_append_reply(msg)
        if was_leader and node.role != "leader":
            self.log(f"{dst} steps down: it saw term {node.current_term}")
            self.reset_election_timer(node)                  # a follower again: it needs a timer

"""A trip-booking saga: book a flight, book a hotel, charge the card; compensate on failure."""
from __future__ import annotations


class StepFailed(Exception):
    """The service refused: the saga can't go forward."""


class TemporaryError(Exception):
    """A timeout or an outage: try again."""


class Service:
    def __init__(self, name: str, refuse: set[str] = frozenset(), flaky_undos: int = 0) -> None:
        self.name = name
        self.refuse = set(refuse)            # trips this service refuses
        self.flaky_undos = flaky_undos       # the first few compensations fail with a TemporaryError
        self.bookings: dict[str, str] = {}

    def do(self, trip: str) -> None:
        if trip in self.refuse:
            raise StepFailed(f"{self.name} refused {trip}")
        self.bookings[trip] = "booked"

    def undo(self, trip: str) -> None:
        """Compensate. Idempotent: cancelling twice, or cancelling something never booked, is harmless."""
        if self.flaky_undos:
            self.flaky_undos -= 1
            raise TemporaryError(f"{self.name} timed out")
        if self.bookings.get(trip) == "booked":
            self.bookings[trip] = "cancelled"


def run_saga(trip: str, steps: list[Service], log: list[str], max_attempts: int = 10) -> str:
    """Run each step in order, appending 'do <name>' to log for each success. If a step raises
    StepFailed, append 'failed <name>', then compensate the completed steps in reverse order, retrying
    each undo after a TemporaryError (append 'retry undo <name>') until it succeeds ('undo <name>').
    Return 'completed' or 'compensated'."""
