"""Raft's safety properties (Figure 3 of the Raft paper) as checks to run after every simulated event.

A snapshot maps each node to its state:
    {"n1": {"term": 3, "role": "leader", "log": [(1, "set x 1"), (3, "noop")], "commit_index": 2}, ...}
Log indexes count from 1 (log[0] is index 1) and commit_index 0 means nothing is committed.
leaders_by_term maps each term to every node that was ever leader in it.
committed lists every commit as {"index": i, "entry": (term, command), "term": term it was committed in}.
"""
from __future__ import annotations


class SafetyViolation(AssertionError):
    pass


def election_safety(leaders_by_term: dict[int, set[str]]) -> None:
    """At most one leader per term."""
    for term, names in leaders_by_term.items():
        if len(names) > 1:
            raise SafetyViolation(f"election safety: term {term} had leaders {sorted(names)}")


def log_matching(snapshot: dict) -> None:
    """If two logs have an entry with the same index and term, they are identical up to that index."""
    names = sorted(snapshot)
    for i, a in enumerate(names):
        for b in names[i + 1:]:
            la, lb = snapshot[a]["log"], snapshot[b]["log"]
            for idx in range(min(len(la), len(lb)) - 1, -1, -1):
                if la[idx][0] == lb[idx][0]:
                    if la[: idx + 1] != lb[: idx + 1]:
                        raise SafetyViolation(f"log matching: {a} and {b} share term {la[idx][0]} at index "
                                              f"{idx + 1} but differ before it")
                    break


def state_machine_safety(snapshot: dict) -> None:
    """No two nodes have committed (and so applied) different entries at the same index."""
    names = sorted(snapshot)
    for i, a in enumerate(names):
        for b in names[i + 1:]:
            n = min(snapshot[a]["commit_index"], snapshot[b]["commit_index"])
            if snapshot[a]["log"][:n] != snapshot[b]["log"][:n]:
                raise SafetyViolation(f"state machine safety: {a} and {b} committed different entries "
                                      f"in their first {n}")


def leader_completeness(snapshot: dict, committed: list[dict]) -> None:
    """A leader of term T holds every entry committed in term T or earlier."""
    for name, s in snapshot.items():
        if s["role"] != "leader":
            continue
        for c in committed:
            if c["term"] <= s["term"]:
                i = c["index"]
                if len(s["log"]) < i or s["log"][i - 1] != c["entry"]:
                    raise SafetyViolation(f"leader completeness: {name} (term {s['term']}) lacks entry {i} "
                                          f"{c['entry']}, committed in term {c['term']}")


def check_all(snapshot: dict, leaders_by_term: dict[int, set[str]], committed: list[dict]) -> None:
    election_safety(leaders_by_term)
    log_matching(snapshot)
    state_machine_safety(snapshot)
    leader_completeness(snapshot, committed)

import pytest

from invariants import (SafetyViolation, check_all, election_safety, leader_completeness, log_matching,
                        state_machine_safety)

GOOD = {
    "n1": {"term": 3, "role": "leader", "log": [(1, "x=1"), (1, "y=2"), (3, "noop")], "commit_index": 3},
    "n2": {"term": 3, "role": "follower", "log": [(1, "x=1"), (1, "y=2"), (3, "noop")], "commit_index": 2},
    "n3": {"term": 2, "role": "follower", "log": [(1, "x=1"), (2, "z=9")], "commit_index": 1},
}
COMMITTED = [{"index": 1, "entry": (1, "x=1"), "term": 1}, {"index": 2, "entry": (1, "y=2"), "term": 3},
             {"index": 3, "entry": (3, "noop"), "term": 3}]


def test_a_healthy_cluster_passes():
    check_all(GOOD, {1: {"n1"}, 2: {"n3"}, 3: {"n1"}}, COMMITTED)


def test_two_leaders_in_one_term():
    with pytest.raises(SafetyViolation):
        election_safety({4: {"n1", "n2"}})


def test_logs_that_share_an_entry_but_not_its_history():
    bad = {"a": {"log": [(1, "x"), (2, "y")]}, "b": {"log": [(1, "w"), (2, "y")]}}
    with pytest.raises(SafetyViolation):
        log_matching(bad)


def test_different_committed_entries():
    bad = {"a": {"log": [(1, "x")], "commit_index": 1}, "b": {"log": [(1, "y")], "commit_index": 1}}
    with pytest.raises(SafetyViolation):
        state_machine_safety(bad)


def test_a_new_leader_missing_a_committed_entry():
    snapshot = {"n3": {"term": 4, "role": "leader", "log": [(1, "x=1"), (2, "z=9")], "commit_index": 1}}
    with pytest.raises(SafetyViolation):
        leader_completeness(snapshot, COMMITTED)


def test_a_stale_leader_need_not_hold_later_commits():
    snapshot = {"n3": {"term": 2, "role": "leader", "log": [(1, "x=1"), (2, "z=9")], "commit_index": 1}}
    leader_completeness(snapshot, COMMITTED)      # entries 2 and 3 were committed in term 3
